// ─── File: CountDownLatchDemo.java ───
// Runnable demo. In a real project each class lives in its own file.
package com.bank.eod;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.logging.*;

public class CountDownLatchDemo {
    private static final Logger LOG = Logger.getLogger("EOD");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        LOG.setUseParentHandlers(false);
        LOG.addHandler(h);
        LOG.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        int workers = 4;
        CountDownLatch startGate = new CountDownLatch(1);       // startup gate
        CountDownLatch doneGate  = new CountDownLatch(workers); // completion gate
        Account rajesh = new Account("SAV2001", new BigDecimal("1000000"));

        ExecutorService pool = Executors.newFixedThreadPool(workers);
        for (int i = 0; i < workers; i++) {
            int slice = i;
            pool.submit(new SettlementWorker(slice, startGate, doneGate, rajesh,
                                             new BigDecimal("10000"), LOG));
        }

        SettlementCoordinator coordinator = new SettlementCoordinator(startGate, doneGate, LOG);
        coordinator.run();   // opens start gate, waits for completion

        LOG.info(() -> "Report: SAV2001 balance = Rs." + rajesh.getBalance());
        pool.shutdown();
    }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String id;
    private BigDecimal balance;
        Account(String id, BigDecimal balance) { this.id = id;
        this.balance = balance; }
    synchronized void debit(BigDecimal amt) { balance = balance.subtract(amt); }
    synchronized BigDecimal getBalance() { return balance; }
    String getId() { return id; }
}

// ─── Would be in worker/SettlementWorker.java ───
class SettlementWorker implements Runnable {
    private final int slice;
    private final CountDownLatch startGate;
    private final CountDownLatch doneGate;
    private final Account account;
    private final BigDecimal amount;
    private final Logger log;
    SettlementWorker(int slice, CountDownLatch startGate, CountDownLatch doneGate,
                     Account account, BigDecimal amount, Logger log) {
            this.slice = slice;
            this.startGate = startGate
            this.doneGate = doneGate;
            this.account = account;
            this.amount = amount
            this.log = log;
    }
    @Override public void run() {
        try {
            startGate.await();                 // wait for the starting gun
            log.info(() -> "worker " + slice + " started settling");
            account.debit(amount);             // settle this slice
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            doneGate.countDown();              // always decrement, even on failure
            log.info(() -> "worker " + slice + " done");
        }
    }
}

// ─── Would be in coordinator/SettlementCoordinator.java ───
class SettlementCoordinator {
    private final CountDownLatch startGate;
    private final CountDownLatch doneGate;
    private final Logger log;
    SettlementCoordinator(CountDownLatch startGate, CountDownLatch doneGate, Logger log) {
            this.startGate = startGate;
            this.doneGate = doneGate
            this.log = log;
    }
    void run() throws InterruptedException {
        log.info("coordinator: firing the starting gun");
        startGate.countDown();                 // release ALL workers at once
        boolean finished = doneGate.await(5, TimeUnit.SECONDS);  // timed completion gate
        if (!finished) { log.severe("coordinator: a worker stalled, raising alert"); return; }
        log.info("coordinator: all workers finished, generating report");
    }
}
