// ─── File: src/test/java/com/bank/eod/coordinator/LatchGateTest.java ───
package com.bank.eod.coordinator;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

class LatchGateTest {
    @Test
    void completionGateWaitsForAllWorkers() throws Exception {
        int n = 3;
        CountDownLatch done = new CountDownLatch(n);
        AtomicInteger counter = new AtomicInteger();
        ExecutorService pool = Executors.newFixedThreadPool(n);
        for (int i = 0; i < n; i++)
            pool.submit(() -> { counter.incrementAndGet(); done.countDown(); });
        assertTrue(done.await(2, TimeUnit.SECONDS));
        assertEquals(n, counter.get());   // coordinator saw all workers finish
        pool.shutdown();
    }
}
